package app.cadence;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;

public final class RecommendationsTest {
    private Track track(int id,String artist){return new Track(String.format(Locale.ROOT,"rec%08d",id),"Song "+id,artist,"https://example.test/"+id,180);}
    private Recommendations.Profile profile(long rotation){return new Recommendations.Profile(List.of(new Library.Taste(track(1,"First artist - Topic"),8,1000,true),new Library.Taste(track(2,"Second artist"),2,2000,false)),List.of(new Library.Search("acoustic guitar",3000,2)),Set.of(),MusicLanguage.PUNJABI,rotation);}
    @Test public void plansUseMultipleTasteSignalsAndDifferentMoodIntents(){
        var profile=profile(0);var excludedSeed=new Recommendations.Profile(profile.taste(),profile.searches(),Set.of(track(1,"First artist").id(),track(2,"Second artist").id()),profile.language(),0);assertTrue(Recommendations.artists(excludedSeed).contains("First artist"));List<String> queries=Recommendations.queries(profile,Recommendations.Mood.FOR_YOU);assertTrue(queries.get(0).contains("First artist"));assertTrue(queries.stream().anyMatch(q->q.contains("acoustic guitar")));assertTrue(Recommendations.playlistQueries(profile).stream().anyMatch(q->q.contains("Second artist")));assertTrue(queries.stream().allMatch(q->q.startsWith("Punjabi ")));
        Set<String> intentQueries=new HashSet<>();for(var mood:List.of(Recommendations.Mood.FOCUS,Recommendations.Mood.CHILL,Recommendations.Mood.ENERGY,Recommendations.Mood.DISCOVERY))assertTrue(intentQueries.add(Recommendations.queries(profile,mood).get(0)));
    }
    @Test public void refreshingChangesTheProfileAndRetrievalPlan(){assertNotEquals(profile(0).fingerprint(),profile(1).fingerprint());assertNotEquals(Recommendations.queries(profile(0),Recommendations.Mood.FOR_YOU),Recommendations.queries(profile(1),Recommendations.Mood.FOR_YOU));}
    @Test public void rankingRemovesDuplicatesHiddenSongsAndLimitsOneArtist(){List<Track> input=new ArrayList<>();for(int i=1;i<12;i++)input.add(track(i,i<7?"First artist":"Other "+i));input.add(input.get(0));var base=profile(0);var p=new Recommendations.Profile(base.taste(),base.searches(),Set.of(input.get(0).id()),base.language(),0);List<Track> ranked=Recommendations.rank(p,Recommendations.Mood.FOR_YOU,input,8);assertFalse(ranked.stream().anyMatch(t->t.id().equals(input.get(0).id())));assertEquals(ranked.size(),ranked.stream().map(Track::id).distinct().count());assertTrue(ranked.stream().filter(t->t.artist().equals("First artist")).count()<=2);}
    @Test public void freshFindsExcludeFamiliarTracksAndRepeatUsesActualHistory(){var p=profile(0);List<Track> result=Recommendations.rank(p,Recommendations.Mood.DISCOVERY,List.of(track(1,"First artist"),track(22,"New artist")),12);assertEquals(List.of(track(22,"New artist")),result);assertEquals(track(1,"First artist - Topic"),Recommendations.repeat(p).get(0));}
    @Test public void retrievalIncludesSearchSignalsEvenWithLargeFirstPage()throws Exception{List<String> calls=new ArrayList<>();Recommendations.load(profile(0),Recommendations.Mood.FOR_YOU,q->{calls.add(q);List<Track> songs=new ArrayList<>();for(int i=0;i<30;i++)songs.add(track(i,"Artist "+i));return songs;});assertEquals(3,calls.size());assertTrue(calls.get(1).contains("acoustic guitar"));}
    @Test public void playlistRetrievalCombinesQueriesAndDeduplicatesUrls()throws Exception{Set<String> queries=new HashSet<>();PlaylistSource source=new PlaylistSource(){public List<Suggestion> suggest(String q){queries.add(q);return List.of(new Suggestion("https://www.youtube.com/playlist?list=PL_shared","Shared","Author","",2),new Suggestion("https://www.youtube.com/playlist?list=PL_"+queries.size(),q,"Author","",2));}public Tracks playlist(String url,org.schabi.newpipe.extractor.Page page){return null;}};var result=Recommendations.playlists(profile(0),source);assertEquals(3,queries.size());assertEquals(4,result.size());}
    @Test public void cachedRetrievalCanBeRerankedWithoutRefetchingTheSameQueries(){var original=profile(0);var changed=new Recommendations.Profile(List.of(new Library.Taste(track(1,"First artist - Topic"),9,9000,true),new Library.Taste(track(2,"Second artist"),2,2000,false)),original.searches(),original.hidden(),original.language(),0);assertNotEquals(original.fingerprint(),changed.fingerprint());assertEquals(Recommendations.retrievalKey(original,Recommendations.Mood.FOR_YOU),Recommendations.retrievalKey(changed,Recommendations.Mood.FOR_YOU));assertNotEquals(Recommendations.retrievalKey(original,Recommendations.Mood.FOR_YOU),Recommendations.retrievalKey(profile(1),Recommendations.Mood.FOR_YOU));}
    @Test public void currentSongAndExplicitStylesGuideRetrievalAndRanking(){var p=profile(0).withCurrent(new Track("rec00000099","Acoustic sunset","New singer - Topic","",180));assertTrue(Recommendations.queries(p,Recommendations.Mood.FOR_YOU).get(0).contains("New singer Acoustic sunset"));assertTrue(Recommendations.styles(p).contains("acoustic"));Track acoustic=new Track("rec00000098","Acoustic dawn","New singer","",180);Track other=track(97,"Unrelated singer");assertEquals(acoustic,Recommendations.rank(p,Recommendations.Mood.FOR_YOU,List.of(other,acoustic,p.current()),12).get(0));assertFalse(Recommendations.rank(p,Recommendations.Mood.FOR_YOU,List.of(p.current()),12).contains(p.current()));}
    @Test public void recentSkipRemovesSongFromEveryMixAndQualifiedListeningRestoresIt(){var base=profile(0);Track skipped=track(1,"First artist");var p=new Recommendations.Profile(base.taste(),base.searches(),base.hidden(),base.language(),0,List.of(new Library.Feedback(skipped.id(),1,0,System.currentTimeMillis())),null);for(var mood:Recommendations.Mood.values())assertFalse(Recommendations.rank(p,mood,List.of(skipped,track(9,"Other")),12).contains(skipped));assertFalse(Recommendations.repeat(p).stream().anyMatch(t->t.id().equals(skipped.id())));var restored=new Recommendations.Profile(base.taste(),base.searches(),Set.of(),base.language(),0,List.of(new Library.Feedback(skipped.id(),1,1,0)),null);assertTrue(Recommendations.rank(restored,Recommendations.Mood.FOR_YOU,List.of(skipped),12).contains(skipped));}
    @Test public void styleWordsUseWordBoundariesAndMoodIntentOutranksGenericAffinity(){var p=new Recommendations.Profile(List.of(),List.of(new Library.Search("popular rapper",1,1)),Set.of(),MusicLanguage.ANY,0);assertTrue(Recommendations.styles(p).isEmpty());Track calm=new Track("rec00000088","Instrumental ambient study","New artist","",180);assertEquals(calm,Recommendations.rank(profile(0),Recommendations.Mood.FOCUS,List.of(track(1,"First artist"),calm),12).get(0));}
    @Test public void providerRelatedCandidatesSurviveSearchFailure()throws Exception{Track related=track(8,"Related singer");MusicCatalog catalog=new MusicCatalog(){public List<Track> related(Track t){return List.of(related);}public Result search(String q,org.schabi.newpipe.extractor.Page p,Mode mode)throws Exception{throw new java.io.IOException("offline search");}};assertEquals(List.of(related),Recommendations.catalogCandidates(profile(0).withCurrent(track(1,"Seed")),Recommendations.Mood.FOR_YOU,catalog));}
}
